#pragma once
#include "kstationControllerParameterEditRuntime.h"
#include "kstationControllerVoiceServices.h"
#include "kstationControllerPanelRefreshRuntime.h"
#include "kstationControllerVoiceSyncRuntime.h"
namespace kstation {
// Board composition for parameter edits: voice, panel and sync use real owners.
class ControllerParameterEditServices final {
 using E=ControllerParameterEditRuntime;using V=ControllerVoiceServices;
public:
 enum class Owner:uint8_t{None,Edit,Voice,Panel};enum class Route:uint8_t{Ready,External,Invalid};struct Request{Owner owner=Owner::None;E::Request edit{};ControllerVoiceRefreshRuntime::Request voice{};};enum class Block:uint8_t{None,Inactive,NotBound,External,NeedsInterrupt};struct Result{unsigned clocks=0;bool returned=false;Block blocked=Block::None;};
 bool bindAll(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_||active())return false;if(!edit_.bindVerifiedFirmware(d,image,size)||!panelRefresh_.bindVerifiedFirmware(d,image,size)||!sync_.bindVerifiedFirmware(d,image,size))return false;bound_=&d;return true;}bool boundTo(const ControllerDeviceState&d)const{return bound_==&d;}bool active()const{return edit_.active();}bool start(uint8_t field,uint8_t value){return !voice_&&!panel_&&!sync_.active()&&edit_.start(field,value);}bool reset(){if(voice_||panel_||sync_.active())return false;edit_.reset();panelRefresh_.reset();sync_.reset();return true;}
 Route route(ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerDspTransferRuntime&dsp,V&voice,ControllerPanelHardwareRuntime&panel){irq_=&irq;if(bound_!=&d||!dsp.boundTo(d)||!voice.boundTo(d)||!panel.boundTo(d)||!active())return Route::Invalid;if(voice_){auto r=voice_->routeParameterRefresh(d,dsp);return r==V::Route::Ready?Route::Ready:r==V::Route::External?Route::External:Route::Invalid;}if(panel_){if(panelRefresh_.nextClocks(d,*irq_,*panel_,dsp))return Route::Ready;if(irq_->active()||(d.pendingIrqs&&irq_->mask()==ControllerInterruptRuntime::Mask::Enabled))return Route::Ready;panelUnsupported_=true;return Route::External;}if(sync_.active())return Route::Ready;auto q=edit_.request();switch(q.service){case E::Service::None:return Route::Ready;case E::Service::Voices:if(!voice.startParameterRefresh())return Route::Invalid;voice_=&voice;dsp_=&dsp;return Route::Ready;case E::Service::Panel:if(panel.active()||dsp.active()||!panelRefresh_.start())return Route::Invalid;panel_=&panel;dsp_=&dsp;panelUnsupported_=false;return Route::Ready;case E::Service::Clock:case E::Service::Effects:if(dsp.active()||!sync_.start(q.service==E::Service::Clock?VoiceSyncTask::Kind::First:VoiceSyncTask::Kind::Second))return Route::Invalid;syncParent_=q.service;dsp_=&dsp;return Route::Ready;default:return Route::External;}}
 Request externalRequest()const{if(voice_)return {Owner::Voice,{},voice_->parameterRefreshRequest()};if(panel_)return panelUnsupported_?Request{Owner::Panel}:Request{};if(sync_.active())return {};auto q=edit_.request();return q.service==E::Service::None?Request{}:Request{Owner::Edit,q};}
 bool completeExternal(const Request&r,uint32_t value=0){if(r.owner==Owner::Voice&&voice_)return voice_->completeParameterRefreshChild(r.voice.child,value);if(r.owner==Owner::Edit&&!voice_&&!panel_&&!sync_.active())return edit_.completeService(r.edit.service);return false;}
 unsigned nextClocks(const ControllerDeviceState&d,const ControllerInterruptRuntime&irq)const{if(bound_!=&d||!active())return 0;if(voice_)return voice_->nextParameterRefresh(d,irq,*dsp_);if(panel_)return panelRefresh_.nextClocks(d,irq,*panel_,*dsp_);if(sync_.active())return sync_.nextClocks(d,irq,*dsp_);return edit_.nextClocks(d,irq);}
 Result advanceBefore(ControllerDeviceState&d,ControllerInterruptRuntime&irq,unsigned budget){if(bound_!=&d)return {0,false,Block::NotBound};if(!active())return {0,false,Block::Inactive};if(voice_){auto r=voice_->advanceParameterRefresh(d,irq,*dsp_,budget);if(r.returned){voice_=nullptr;dsp_=nullptr;if(!edit_.completeService(E::Service::Voices))return {r.clocks,false,Block::External};}return {r.clocks,false,r.blocked==ControllerVoiceRefreshRuntime::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==ControllerVoiceRefreshRuntime::Block::AwaitChild?Block::External:Block::None};}if(panel_){auto r=panelRefresh_.advanceBefore(d,irq,*panel_,*dsp_,budget);if(r.returned){panel_=nullptr;dsp_=nullptr;if(!edit_.completeService(E::Service::Panel))return {r.clocks,false,Block::External};}if(r.blocked==ControllerPanelRefreshRuntime::Block::UnsupportedHandler){panelUnsupported_=true;return {r.clocks,false,Block::External};}return {r.clocks,false,r.blocked==ControllerPanelRefreshRuntime::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==ControllerPanelRefreshRuntime::Block::ServiceBusy?Block::External:Block::None};}if(sync_.active()){auto r=sync_.advanceBefore(d,irq,*dsp_,budget);if(r.returned){dsp_=nullptr;if(!edit_.completeService(syncParent_))return {r.clocks,false,Block::External};syncParent_=E::Service::None;}return {r.clocks,false,r.blocked==ControllerVoiceSyncRuntime::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==ControllerVoiceSyncRuntime::Block::DspBusy?Block::External:Block::None};}auto r=edit_.advanceBefore(d,irq,budget);return {r.clocks,r.returned,r.blocked==E::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==E::Block::AwaitService?Block::External:Block::None};}
private:ControllerDeviceState*bound_=nullptr;E edit_{};ControllerPanelRefreshRuntime panelRefresh_{};ControllerVoiceSyncRuntime sync_{};V*voice_=nullptr;ControllerPanelHardwareRuntime*panel_=nullptr;ControllerDspTransferRuntime*dsp_=nullptr;ControllerInterruptRuntime*irq_=nullptr;bool panelUnsupported_=false;E::Service syncParent_=E::Service::None;
};
}
